def _dump(node):
    return ast.dump(node, include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code, field) for field in (
        'co_code', 'co_names', 'co_varnames', 'co_argcount', 'co_posonlyargcount',
        'co_kwonlyargcount', 'co_flags', 'co_freevars', 'co_cellvars')) + (tuple(
            _code_shape(value) if type(value) is CodeType else value
            for value in code.co_consts),)


def _function(tree, name):
    found = [node for node in tree.body if type(node) is ast.FunctionDef and node.name == name]
    if len(found) != 1:
        raise Boundary('one complete cold assembly source owner required: ' + name)
    return found[0]


def _top_code(code, name):
    found = [value for value in code.co_consts if type(value) is CodeType
        and value.co_name == name and value.co_qualname == name]
    if len(found) != 1:
        raise Boundary('one complete top-level cold assembly code owner required: ' + name)
    return found[0]


def _loaded(module, name, expected):
    original = getattr(module, name)
    tree = ast.parse(inspect.getsource(module), filename=module.__file__)
    if (_dump(_function(tree, name)) != expected or type(original) is not FunctionType
            or original.__module__ != module.__name__ or original.__name__ != name
            or original.__globals__ is not vars(module) or original.__closure__ is not None
            or original.__code__.co_freevars or inspect.isgeneratorfunction(original)):
        raise Boundary('actual unchanged complete cold construction function required: ' + name)
    code = compile(tree, original.__code__.co_filename, 'exec', dont_inherit=True)
    if _code_shape(_top_code(code, name)) != _code_shape(original.__code__):
        raise Boundary('loaded cold construction differs from its complete source: ' + name)
    return original, tree


def _city_entry_module(original_tree):
    """Finite fresh-construction changes, with an entire-module inverse.

    Keep original VDP/bare, Input/VDP and Sound/Input construction intact.
    Attach Save only to the complete sound chain passed into WriteDMA, before
    a Scene exists. No actual MMIO owner or running device is replaced.
    """
    tree = copy.deepcopy(original_tree)
    function = _function(tree, 'run')
    originals = {}
    for index, node in enumerate(function.body):
        if type(node) is not ast.ImportFrom or node.module not in ENTRY_IMPORTS:
            continue
        if node.level != 0 or node.module in originals:
            raise Boundary('exact unique absolute cold family import required')
        module, pairs = ENTRY_IMPORTS[node.module]
        if [(item.name, item.asname) for item in node.names] != [(old, None) for old, new in pairs]:
            raise Boundary('complete original cold family import changed')
        originals[node.module] = (index, copy.deepcopy(node))
        function.body[index] = ast.copy_location(ast.ImportFrom(module=module, level=0,
            names=[ast.alias(name=new, asname=old if old != new else None) for old, new in pairs]), node)
    if set(originals) != set(ENTRY_IMPORTS):
        raise Boundary('both exact whole reset and installation imports are required')
    pcm_devices = {'YmfmDevice': '_city_fm_pcm_sink', 'SegaPsgDevice': '_city_psg_pcm_sink'}
    pcm_sites = {name: 0 for name in pcm_devices}
    for node in ast.walk(function):
        if type(node) is not ast.Call or type(node.func) is not ast.Name or node.func.id not in pcm_devices:
            continue
        sinks = [item for item in node.keywords if item.arg == 'pcm_sink']
        if len(sinks) != 1 or type(sinks[0].value) is not ast.Constant or sinks[0].value.value is not None:
            raise Boundary('actual fresh chip constructor must have one explicit unbound PCM sink')
        pcm_sites[node.func.id] += 1
        sinks[0].value = ast.Name(id=pcm_devices[node.func.id], ctx=ast.Load())
    if any(count != 1 for count in pcm_sites.values()):
        raise Boundary('one actual fresh FM and PSG constructor is required')
    dma_calls = [node for node in ast.walk(function) if type(node) is ast.Call
        and type(node.func) is ast.Name and node.func.id == 'SceneWriteDmaEvents']
    expected_dma = ast.parse('SceneWriteDmaEvents(sound_bus, vdp, '
        "tuple(WriteDmaGrant(**row) for row in video_input['write_DMA_grants']))", mode='eval').body
    if len(dma_calls) != 1 or _dump(dma_calls[0]) != _dump(expected_dma):
        raise Boundary('one complete original WriteDMA constructor with the actual sound chain required')
    dma_calls[0].args[0] = ast.Call(func=ast.Name(id='_city_save_device_chain', ctx=ast.Load()),
        args=[ast.Name(id='sound_bus', ctx=ast.Load())], keywords=[])
    # Preserve truthful callback selections in the retained parent's receipt.
    # This changes metadata only, never a chip operation or timing supply.
    receipt_labels = {'actual_YMFM': '_city_fm_pcm_receipt_label',
        'actual_same_PSG': '_city_psg_pcm_receipt_label'}
    receipt_sites = {key: 0 for key in receipt_labels}
    for node in ast.walk(function):
        if type(node) is not ast.Assign or len(node.targets) != 1:
            continue
        for key, binding in receipt_labels.items():
            expected = ast.parse('receipt[' + repr(key) + '] = None').body[0].targets[0]
            if _dump(node.targets[0]) != _dump(expected):
                continue
            if type(node.value) is not ast.Call:
                raise Boundary('complete original device receipt constructor required')
            labels = [item for item in node.value.keywords if item.arg == 'PCM_sink']
            if (len(labels) != 1 or type(labels[0].value) is not ast.Constant
                    or labels[0].value.value != 'explicitly_discarded_no_WAV'):
                raise Boundary('one original discarded-PCM label per actual device required')
            labels[0].value = ast.Name(id=binding, ctx=ast.Load())
            receipt_sites[key] += 1
    if any(count != 1 for count in receipt_sites.values()):
        raise Boundary('both actual device PCM receipt selections are required')
    # Bind the unchanged exact material constructor to the same source authority.
    # This occurs before AudioState/Scene construction, never on a running bus.
    old_material = ast.parse('OwnedSoundMaterial(bank.data, (), bank.resource_ids, bank.encoded_bytes)', mode='eval').body
    material_sites = [node for node in ast.walk(function) if type(node) is ast.Call
        and _dump(node) == _dump(old_material)]
    if len(material_sites) != 1:
        raise Boundary('one complete original five-package material constructor required')
    material = material_sites[0]
    preserved_material = copy.deepcopy(material)
    material.func = ast.Name(id='_city_cartridge_material', ctx=ast.Load())
    material.args = [ast.Name(id='source', ctx=ast.Load()), preserved_material,
        ast.Name(id='receipt', ctx=ast.Load())]
    material.keywords = []
    old_first_wait = ast.parse('reset.main_session.suspensions != 1', mode='eval').body
    new_first_wait = ast.parse('not reset.require_first_main_wait(reset.main_session, waiting)',
        mode='eval').body
    first_wait_sites = []

    class FirstMainWait(ast.NodeTransformer):
        def visit_Compare(self, node):
            if _dump(node) == _dump(old_first_wait):
                first_wait_sites.append(copy.deepcopy(node))
                return ast.copy_location(copy.deepcopy(new_first_wait), node)
            return self.generic_visit(node)

    FirstMainWait().visit(function)
    if len(first_wait_sites) != 1:
        raise Boundary('one original one-suspension assertion must become the exact city first3BC proof')
    inverse = copy.deepcopy(tree)
    restored = _function(inverse, 'run')
    for index, old in originals.values():
        restored.body[index] = old
    for node in ast.walk(restored):
        if type(node) is ast.Call and type(node.func) is ast.Name and node.func.id in pcm_devices:
            sink = next(item for item in node.keywords if item.arg == 'pcm_sink')
            if type(sink.value) is not ast.Name or sink.value.id != pcm_devices[node.func.id]:
                raise Boundary('fresh PCM sink inverse differs')
            sink.value = ast.Constant(value=None)
    inverse_dma = [node for node in ast.walk(restored) if type(node) is ast.Call
        and type(node.func) is ast.Name and node.func.id == 'SceneWriteDmaEvents']
    expected_save = ast.parse('_city_save_device_chain(sound_bus)', mode='eval').body
    if len(inverse_dma) != 1 or _dump(inverse_dma[0].args[0]) != _dump(expected_save):
        raise Boundary('exact fresh Save attachment inverse differs')
    inverse_dma[0].args[0] = ast.Name(id='sound_bus', ctx=ast.Load())
    for node in ast.walk(restored):
        if type(node) is not ast.Assign or len(node.targets) != 1:
            continue
        for key, binding in receipt_labels.items():
            if _dump(node.targets[0]) != _dump(ast.parse('receipt[' + repr(key) + '] = None').body[0].targets[0]):
                continue
            label = next(item for item in node.value.keywords if item.arg == 'PCM_sink')
            if type(label.value) is not ast.Name or label.value.id != binding:
                raise Boundary('actual device PCM receipt label inverse differs')
            label.value = ast.Constant(value='explicitly_discarded_no_WAV')
    expected_material = ast.parse('_city_cartridge_material(source, '
        'OwnedSoundMaterial(bank.data, (), bank.resource_ids, bank.encoded_bytes), receipt)', mode='eval').body
    restored_material_sites = [node for node in ast.walk(restored) if type(node) is ast.Call
        and _dump(node) == _dump(expected_material)]
    if len(restored_material_sites) != 1:
        raise Boundary('the exact same-source material binding inverse differs')
    restored_material = restored_material_sites[0]
    restored_material.func = copy.deepcopy(old_material.func)
    restored_material.args = copy.deepcopy(old_material.args)
    restored_material.keywords = copy.deepcopy(old_material.keywords)
    first_wait_restored = []

    class RestoreFirstMainWait(ast.NodeTransformer):
        def visit_UnaryOp(self, node):
            if _dump(node) == _dump(new_first_wait):
                first_wait_restored.append(node)
                return ast.copy_location(copy.deepcopy(old_first_wait), node)
            return self.generic_visit(node)

    RestoreFirstMainWait().visit(restored)
    if len(first_wait_restored) != 1:
        raise Boundary('the exact city first3BC assertion inverse differs')
    if _dump(inverse_dma[0]) != _dump(expected_dma) or _dump(inverse) != _dump(original_tree):
        raise Boundary('entire derived cold assembly module inverse differs')
    return ast.fix_missing_locations(tree)


def _city_live_factory_tree(original_tree):
    """One private compilation-argument change, after the original inverse.

    Original live factory transformations and their admission remain intact.
    It still compiles the whole original module and constructs its one live
    generator without calling the old runner or executing module imports.
    """
    original = _function(original_tree, '_derived_factory')
    if _dump(original) != EXPECTED_LIVE_FACTORY_AST:
        raise Boundary('complete original live cold factory differs')
    old = ast.parse("compile(ast.fix_missing_locations(derived_module), original.__code__.co_filename, 'exec')", mode='eval').body
    new = ast.parse("compile(_city_entry_module(ast.fix_missing_locations(derived_module)), original.__code__.co_filename, 'exec')", mode='eval').body
    hits = []

    class Lift(ast.NodeTransformer):
        def visit_Call(self, node):
            if _dump(node) == _dump(old):
                hits.append(node)
                return ast.copy_location(copy.deepcopy(new), node)
            return self.generic_visit(node)

    derived = Lift().visit(copy.deepcopy(original))
    if len(hits) != 1:
        raise Boundary('one final original live module compilation site required')
    undo = []

    class Inverse(ast.NodeTransformer):
        def visit_Call(self, node):
            if _dump(node) == _dump(new):
                undo.append(node)
                return ast.copy_location(copy.deepcopy(old), node)
            return self.generic_visit(node)

    inverse = Inverse().visit(copy.deepcopy(derived))
    if len(undo) != 1 or _dump(inverse) != _dump(original):
        raise Boundary('entire cold factory function inverse differs')
    result = copy.deepcopy(original_tree)
    position = original_tree.body.index(original)
    result.body[position] = derived
    restored = copy.deepcopy(result)
    restored.body[position] = inverse
    if _dump(restored) != _dump(original_tree):
        raise Boundary('entire live cold factory module inverse differs')
    return ast.fix_missing_locations(result)


def _make_city_factory(save_image, fm_pcm_sink, psg_pcm_sink):
    if type(save_image) is not SaveImage:
        raise ValueError('one explicit existing live SaveImage is required before cold construction')
    if any(value is not None and not callable(value) for value in (fm_pcm_sink, psg_pcm_sink)):
        raise ValueError('both fresh PCM sink choices must be explicit None or callbacks')
    original_run, _ = _loaded(live.original195, 'run', EXPECTED_ORIGINAL_ASSEMBLY_AST)
    original, tree = _loaded(live, '_derived_factory', EXPECTED_LIVE_FACTORY_AST)
    original_base, _ = _loaded(live, '_base_bus', EXPECTED_BASE_BUS_AST)
    derived = _city_live_factory_tree(tree)
    code = _top_code(compile(derived, original.__code__.co_filename,
        'exec', dont_inherit=True), '_derived_factory')
    namespace = dict(vars(live))
    if '_city_entry_module' in namespace:
        raise Boundary('new city construction binding must not shadow an existing live binding')
    namespace['_city_entry_module'] = _city_entry_module
    view = FunctionType(code, namespace, original.__name__, original.__defaults__, None)
    view.__kwdefaults__ = original.__kwdefaults__

    def save_device_chain(devices):
        # Actual mapping constructors run before this call. Keep their exact
        # local owners, and place Save below all existing after-write layers.
        from .hardware_scene import SceneSoundHardwareBus
        if live._base_bus is not original_base:
            raise Boundary('actual cold base-device constructor was rebound')
        if type(devices) is not SceneSoundHardwareBus or devices.sound.scene is not None:
            raise Boundary('fresh actual unmapped-to-Scene sound chain required for Save attachment')
        return SceneSaveHardwareBus(save_image, devices)

    material_compositor = compose_cartridge_sound_material

    def cartridge_material(source, selected, receipt):
        if compose_cartridge_sound_material is not material_compositor:
            raise Boundary('the fresh same-source material compositor was rebound')
        if (type(receipt) is not dict or type(receipt.get('owned_audio_bank')) is not dict
                or receipt['owned_audio_bank'].get('resource_ids') != list(selected.resource_ids)
                or receipt['owned_audio_bank'].get('encoded_DATA_bytes') != selected.encoded_bytes):
            raise Boundary('the retained original five-package material receipt differs')
        material, evidence = material_compositor(source, selected)
        receipt['owned_audio_bank']['actual_bank_read_authority'] = evidence
        return material

    def family(profile):
        if live._derived_factory is not original or live.original195.run is not original_run:
            raise Boundary('actual complete live construction owner was rebound')
        program = view(profile)
        if program.__globals__['_live_base_bus'] is not original_base:
            raise Boundary('actual original live bare-device construction binding changed')
        private_bindings = ('_city_save_device_chain', '_city_fm_pcm_sink', '_city_psg_pcm_sink',
            '_city_fm_pcm_receipt_label', '_city_psg_pcm_receipt_label', '_city_cartridge_material')
        if any(name in program.__globals__ for name in private_bindings):
            raise Boundary('fresh device/PCM names must not shadow original construction bindings')
        program.__globals__.update(_city_cartridge_material=cartridge_material,
            _city_save_device_chain=save_device_chain,
            _city_fm_pcm_sink=fm_pcm_sink, _city_psg_pcm_sink=psg_pcm_sink,
            _city_fm_pcm_receipt_label=('explicitly_discarded_no_WAV' if fm_pcm_sink is None
                else 'explicit_application_PCM_callback_before_construction'),
            _city_psg_pcm_receipt_label=('explicitly_discarded_no_WAV' if psg_pcm_sink is None
                else 'explicit_application_PCM_callback_before_construction'))
        contract = program.__globals__['_live_contract']
        contract['city_cold_family'] = dict(
            confidence='confirmed_source_only_complete_family_and_device_composition_inverses',
            chosen_before_original206_and300=True, complete_live_factory_inverse=True,
            whole_derived_assembly_module_import_inverse=True, exact_local_import_changes=2,
            exact_private_base_bus_binding_changes=0, exact_save_constructor_argument_changes=1,
            original_VDP_Input_Sound_mapping_and_bind_locals_retained=True,
            fresh_PCM_constructor_keyword_changes=2,
            actual_device_PCM_receipt_label_changes=2,
            PCM_sinks_chosen_before_any_chip_construction=True,
            device_or_sink_hot_swaps=False,
            same_cartridge_sound_material_bound_before_AudioState_and_Scene=True,
            exact_five_package_constructor_wrappers=1, five_package_byte_admission_retained=True,
            actual_audio_bank_uses_same_full_Scene_ReadOnlyData=True,
            original_narrow_material_and_OwnedAudioDeviceBus_defaults_unchanged=True,
            same_explicit_save_backing_bytes=8192,
            save_mapping='odd BYTE lanes200001..203FFF; WriteDMA/Save/Sound/Input/VDP/bare before Scene',
            inherited_Save_after_write_forwards_inner_VDP_before_WriteDMA_grants=True,
            save_backing_or_permissions_inferred=False,
            original_live_finally_and_cleanup_retained=True,
            no_business_algorithm_or_hardware_guard_change=True,
            runtime_or_visual_acceptance_claimed=False, formal_new_CODE_bytes=0)
        return program

    return family


def build_city_cold_driver(project_root, sound_native_root, sources, audio_root, chip_library, inputs, output,
        *, save_image: SaveImage, fm_pcm_sink, psg_pcm_sink):
    """Build one new complete cold/city/battle lifetime from explicit sources.

    Calling this function actually starts the original software, including its
    checksum traversal; importing it does not. The output path must be fresh
    and inside the project's build directory, as the unchanged builder checks.
    No fixture, pad plan, ROM path, default phase or successful ACK is supplied.
    """
    original, _ = _loaded(live, 'build_live_cold_driver', EXPECTED_LIVE_BUILD_AST)
    namespace = dict(vars(live))
    namespace['_derived_factory'] = _make_city_factory(save_image, fm_pcm_sink, psg_pcm_sink)
    builder = FunctionType(original.__code__, namespace, original.__name__, original.__defaults__, None)
    builder.__kwdefaults__ = original.__kwdefaults__
    rig = builder(*(Path(value) for value in (
        project_root, sound_native_root, sources, audio_root, chip_library, inputs, output)))
    from ..high_level_main_flows.city_cold_reset import CityColdResetSession
    from ..high_level_main_flows.city_scene_steps import PersistentCitySceneSession
    if type(rig) is not live.LiveColdDriverRig or type(rig.reset) is not CityColdResetSession:
        raise Boundary('actual retained complete city cold reset rig required')
    if type(rig.main_session) is not PersistentCitySceneSession:
        raise Boundary('the true cold tail did not enter the preselected complete city/battle Main')
    rig.source_contract['city_cold_family']['runtime_family_selected'] = True
    rig.receipt['city_cold_family_selected'] = True
    rig.receipt['complete_game_or_visual_acceptance_claimed'] = False
    return rig.require_live()
